<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        GPIOx-&gt;BSRR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GPIO_Pin;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    // 低16位：设置</span></span>
